select left(stem,100) from questions q join subject_groups g on g.id=q.subject_group_id where g.code='statistics' and (stem ilike '%ogive%' or stem ilike '%odds%' or stem ilike '%coefficient of determination%' or stem ilike '%class mark%' or stem ilike '%mid-value%' or stem ilike '%p-value is 0.0%' or stem ilike '%pie chart%' or stem ilike '%z-score of%' or stem ilike '%committee%' or stem ilike '%continuous variable%' or stem ilike '%probability sampling%' or stem ilike '%mutually exclusive%' or stem ilike '%expected number%' or stem ilike '%E(X²)%' or stem ilike '%slope%' or stem ilike '%median of%');
